before:
import { RequestTelemetry } from '../../lib/parcel-kit.js';

export function inspectImportManifest(manifest) {
  RequestTelemetry.capturePayload('import-inspected', {
    manifest,
    token: manifest.accessToken,
  });
  return manifest.entries.map(entry => entry.kind);
}

after:
import { audits } from '../../lib/parcel-client.js';

export function inspectImportManifest(manifest) {
  audits.record('import-inspected', {
    operationId: manifest.runId,
    count: manifest.entries.length,
    outcome: 'inspected',
  });
  return manifest.entries.map(entry => entry.kind);
}
